package com.yeyamo_mobile.api.partner_service.interfaces.rest;
import com.yeyamo_mobile.api.partner_service.domain.model.BusinessType;import com.yeyamo_mobile.api.partner_service.infrastructure.persistence.*;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;
public final class ArtisanDtos{private ArtisanDtos(){}public record Request(@NotBlank@Size(max=180)String displayName,@NotBlank String story,@NotBlank String craftDescription,@Min(0)Integer yearsOfExperience,@NotBlank@Size(min=2,max=2)String countryCode,String adminLevel1Id,String cityId,String localityId,@NotEmpty Set<String>languages,@NotEmpty Set<UUID>specialtyIds,boolean acceptsCustomOrders,boolean internationalShipping,@NotNull BusinessType artisanType){}public record Specialty(UUID id,String code,String name,String description){public static Specialty from(ArtisanSpecialtyEntity s){return new Specialty(s.getId(),s.getCode(),s.getName(),s.getDescription());}}public record Response(UUID partnerId,String displayName,String story,String craftDescription,Integer yearsOfExperience,String countryCode,String adminLevel1Id,String cityId,String localityId,Set<String>languages,List<Specialty>specialties,boolean acceptsCustomOrders,boolean internationalShipping,ArtisanProfileEntity.VerificationStatus verificationStatus,boolean featured,Instant createdAt,Instant updatedAt){public static Response from(ArtisanProfileEntity p){return new Response(p.getPartnerId(),p.getDisplayName(),p.getStory(),p.getCraftDescription(),p.getYearsOfExperience(),p.getCountryCode(),p.getAdminLevel1Id(),p.getCityId(),p.getLocalityId(),p.getLanguages(),p.getSpecialties().stream().map(Specialty::from).sorted(Comparator.comparing(Specialty::name)).toList(),p.isAcceptsCustomOrders(),p.isInternationalShipping(),p.getVerificationStatus(),p.isFeatured(),p.getCreatedAt(),p.getUpdatedAt());}}public record VerificationRequest(@NotNull ArtisanProfileEntity.VerificationStatus status,@NotBlank String reason){}}
